/** Whether a page opens, sends the person to sign in first, or is refused. */
export function decide(permission, session) {
  if (permission === "public") {
    return "allowed";
  }
  if (!session.signedIn) {
    return "sign-in";
  }
  if (permission === "signedIn") {
    return "allowed";
  }
  return session.permissions.includes(permission) ? "allowed" : "refused";
}

/** The permissions the person holds, signedIn among them once signed in. */
export function permissionsOf(session) {
  if (!session) {
    return [];
  }
  return session.signedIn ? [...session.permissions, "signedIn"] : session.permissions;
}

/** The route of the person's home: that of the first of their roles, in the session's order, that has one. */
export function homeOf(homes, session) {
  return (session.roles ?? []).map((role) => homes[role]).find((route) => route !== undefined);
}

/** The menu as a person sees it: only the entries whose page opens to them, and no empty group. */
export function visibleMenu(menu, session) {
  return menu
    .map((group) => ({ ...group, items: group.items.filter((item) => decide(item.permission, session) === "allowed") }))
    .filter((group) => group.items.length > 0);
}
